    using (
      with
        factor := (
          case tier
            when logistics::shipping_tier.Ground then 1.00
            when logistics::shipping_tier.Express then 1.25
            when logistics::shipping_tier.Overnight then 1.50
          end
        ),
        floor := (
          case tier
            when logistics::shipping_tier.Ground then 500
            when logistics::shipping_tier.Express then 1000
            when logistics::shipping_tier.Overnight then 2000
